schemas.schema-02-actors.prisma:
/// Customer account table with email/password authentication, profile
/// information, and account status. Stores core customer identity data
/// separate from authentication tables for proper separation of concerns.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's email address for login and communication. Must be unique
  /// across all customer accounts.
  email String

  /// Hashed password for authentication. Stored securely using bcrypt or
  /// similar algorithm.
  password_hash String

  /// Public display name shown to other users during transactions and reviews.
  display_name String

  /// Customer's phone number for contact and order notifications.
  phone_number String?

  /// Whether customer has verified their email address through verification
  /// email.
  is_email_verified Boolean

  /// Current account status: active, banned, or deleted.
  status String

  /// Timestamp when customer account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when customer account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when customer account was soft-deleted (if applicable).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions shopping_mall_customer_sessions[]
  passwordResets shopping_mall_customer_password_resets[]
  emailVerifications shopping_mall_customer_email_verifications[]
  inventoryHistories shopping_mall_inventory_histories[]
  wishlists shopping_mall_wishlists[]
  cartItems shopping_mall_carts[]
  orders shopping_mall_orders[]
  cancellationRequests shopping_mall_cancellation_requests[]
  refundRequests shopping_mall_refund_requests[]
  reviews shopping_mall_reviews[]
  reviewSnapshots shopping_mall_review_snapshots[]
  cancellationRequestSnapshots shopping_mall_cancellation_request_snapshots[]

  @@unique([email])
  @@index([status])
  @@index([created_at])
  @@index([updated_at])
  @@index([email, created_at])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([phone_number(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Customer session table with JWT tokens for authentication. Tracks login
/// sessions including connection metadata such as IP address, accessed URL,
/// and referrer information. Each customer can have multiple active sessions
/// from different devices or browsers. This table serves as the audit trail
/// for customer authentication events and enables session management
/// capabilities including logout from all devices.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customer_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link shopping_mall_customers.id}.
  shopping_mall_customer_id String @db.Uuid

  /// Client IP address at time of login.
  ip String

  /// Accessed URL or page path.
  href String?

  /// Referrer URL from which customer arrived.
  referrer String?

  /// Timestamp when session was created (login time).
  created_at DateTime @db.Timestamptz

  /// Timestamp when session expires and becomes invalid.
  expired_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)

  refundRequests shopping_mall_refund_requests[]
  cancellationRequestSnapshots shopping_mall_cancellation_request_snapshots[]

  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, created_at], map: "shopping_mall_customer_sessions_shopping_mall_customer_adefa402")
}

/// Password reset tokens for customer account recovery. Stores secure
/// tokens, expiration timestamps, and reset status for customer password
/// management workflow.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customer_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer's {@link shopping_mall_customers.id} requesting password reset.
  shopping_mall_customer_id String @db.Uuid

  /// Unique password reset token (UUID format) for secure password recovery.
  token String

  /// Token expiration timestamp. Reset attempts are invalid after this time.
  expired_at DateTime @db.Timestamptz

  /// Timestamp when token was successfully used for password reset. Null if
  /// unused or expired.
  used_at DateTime? @db.Timestamptz

  /// Token creation timestamp with timezone information.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_customer_password_resets_shopping_mall_c_08961f19")

  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id], map: "shopping_mall_customer_password_resets_shopping_mall_c_be72fd81")
  @@index([expired_at])
}

/// Email verification tokens for customer account confirmation
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customer_email_verifications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged customer's {@link shopping_mall_customers.id}
  shopping_mall_customer_id String @db.Uuid

  /// Unique verification token generated for email confirmation
  token String

  /// Expiry timestamp for the verification token
  expired_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_customer_email_verifications_shopping_ma_1ccd5d66")

  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id], map: "shopping_mall_customer_email_verifications_shopping_ma_776c5ca9")

  @@unique([token])
}

/// Seller account table with email/password authentication, shop profile,
/// and approval status
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address for authentication and communication
  email String

  /// Hashed password for secure authentication
  password_hash String

  /// Current shop name displayed to customers
  shop_name String

  /// Shop description for customer information
  shop_description String?

  /// Reference to the logo image file
  logo_image_id String? @db.Uuid

  /// Approval status for seller functionality
  status String

  /// Reason for rejection if application was denied
  rejection_reason String?

  /// Timestamp when the seller account was created
  created_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was last updated
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the seller account was deleted (soft delete)
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions shopping_mall_seller_sessions[]
  passwordResets shopping_mall_seller_password_resets[]
  emailVerifications shopping_mall_seller_email_verifications[]
  products shopping_mall_products[]
  cancellationRequests shopping_mall_cancellation_requests[]
  refundRequests shopping_mall_refund_requests[]
  refundRequestResponses shopping_mall_refund_request_responses[]
  shipments shopping_mall_shipments[]
  snapshots shopping_mall_sellers_snapshots[]
  cancellationRequestSnapshots shopping_mall_cancellation_request_snapshots[]

