/// Seller session table storing authentication sessions with JWT tokens,
/// connection metadata, and session lifecycle tracking for the
/// shopping_mall_sellers actor table. Each seller can have multiple
/// concurrent sessions across different devices and browsers.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_seller_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller's {@link shopping_mall_sellers.id}.
  shopping_mall_seller_id String @db.Uuid

  /// Client IP address at the time of login.
  ip String

  /// Current URL/href where the login occurred.
  href String

  /// Referrer URL from which the user arrived at the login page.
  referrer String

  /// Timestamp when the session was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the session expires. Non-null by default for security.
  expired_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller shopping_mall_sellers @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade)

  refundRequestResponses shopping_mall_refund_request_responses[]
  cancellationRequestSnapshots shopping_mall_cancellation_request_snapshots[]

  // spellchecker: ignore-next-line
  @@index([shopping_mall_seller_id, created_at], map: "shopping_mall_seller_sessions_shopping_mall_seller_id__0b9ab7e6")
  @@index([expired_at])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_seller_id, expired_at], map: "shopping_mall_seller_sessions_shopping_mall_seller_id__263ab0dd")
}

/// Password reset tokens for seller account recovery. Stores temporary
/// tokens that sellers can use to reset their passwords when forgotten. Each
/// token is unique, time-limited, and can only be used once. After use, the
/// token becomes invalid and cannot be reused for security reasons.
///
/// This table supports the seller authentication workflow by providing a
/// secure mechanism for password recovery without storing actual passwords
/// in the system.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_seller_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller account requesting password reset. {@link
  /// shopping_mall_sellers.id}.
  shopping_mall_seller_id String @db.Uuid

  /// Unique password reset token generated for security. This token is
  /// included in the password reset URL sent to the seller's registered email
  /// address.
  token String

  /// Expiration datetime for this password reset token. Tokens should expire
  /// after a reasonable time period (typically 1-2 hours) to prevent
  /// unauthorized use.
  expires_at DateTime @db.Timestamptz

  /// Datetime when this token was actually used to reset the password. NULL
  /// until the token is used, indicating the reset request is still pending or
  /// expired.
  used_at DateTime? @db.Timestamptz

  /// Timestamp when this password reset request was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this record was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for audit trail preservation. NULL for active
  /// records, set when record is soft-deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  seller shopping_mall_sellers @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade, map: "shopping_mall_seller_password_resets_shopping_mall_sel_b4e7cfe0")

  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_seller_id], map: "shopping_mall_seller_password_resets_shopping_mall_sel_312ba434")
  @@index([expires_at])
}

/// Email verification tokens for seller account confirmation. This table
/// tracks all email verification attempts for seller accounts, enabling the
/// email verification workflow required during seller registration. Each
/// seller can have multiple verification records over time, supporting both
/// initial registration and re-verification scenarios.
///
/// @{\link shopping_mall_sellers.id} - References the seller account being
/// verified
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_seller_email_verifications {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller account being verified. @{\link shopping_mall_sellers.id}.
  shopping_mall_seller_id String @db.Uuid

  /// Unique verification token for email confirmation.
  token String

  /// Timestamp when verification token expires.
  expired_at DateTime @db.Timestamptz

  /// Timestamp when email was successfully verified (nullable until verified).
  verified_at DateTime? @db.Timestamptz

  /// Creation timestamp for audit trail.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for audit trail.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for audit compliance (nullable when not deleted).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  seller shopping_mall_sellers @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade, map: "shopping_mall_seller_email_verifications_shopping_mall_91ba9685")

  @@unique([token])
  // spellchecker: ignore-next-line
  @@unique([shopping_mall_seller_id], map: "shopping_mall_seller_email_verifications_shopping_mall_875e8d5f")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_seller_id, created_at], map: "shopping_mall_seller_email_verifications_shopping_mall_870f9e98")
  @@index([expired_at])
}

/// Admin account table with email/password authentication and admin privileges
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address for admin account login and notifications
  email String

  /// Hashed password for authentication security
  password_hash String

  /// Admin's display name for identification in system operations
  display_name String

  /// Account status indicating active or deactivated state
  status String

  /// Timestamp when the admin account was created
  created_at DateTime @db.Timestamptz

  /// Timestamp when the admin account was last updated
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the admin account was soft-deleted (nullable if not
  /// deleted)
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  sessions shopping_mall_admin_sessions[]
  passwordResets shopping_mall_admin_password_resets[]
  emailVerifications shopping_mall_admin_email_verifications[]

  @@unique([email])
  @@index([status])
  @@index([created_at])
