    status: shipment.status,
    shipped_at: null,
    delivered_at: null,
    customer_confirmed_delivery: shipment.customer_confirmed_delivery,
    shipping_address: shipment.shipping_address,
    created_at: shipment.created_at,
    updated_at: shipment.updated_at,
  };
