@Controller("/shoppingMall/customer/carts")
export class ShoppingmallCustomerCartsController {
  /**
   * Retrieve the current customer's shopping cart items.
   *
   * This endpoint fetches all active shopping cart items belonging to the authenticated customer. It provides comprehensive information about each cart item including the selected product variants, quantities, and current availability status.
   *
   * The endpoint serves as a critical component of the shopping experience workflow, allowing customers to review their cart contents before proceeding to checkout or making modifications. It displays real-time stock availability information and handles unavailable items gracefully.
   *
   * Security considerations ensure customers can only access their own cart items. The system filters cart items by the authenticated customer's ID and excludes any soft-deleted items.
   *
   * @param connection
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query shopping_mall_carts table to retrieve all active cart items for the authenticated customer.
   *
   * Implementation steps:
   * 1. Extract authenticated customer ID from JWT token
   * 2. Query shopping_mall_carts table with WHERE clause filtering by customer ID
   * 3. Join with shopping_mall_product_variants to get variant details
   * 4. Join with shopping_mall_products to get product information
   * 5. Exclude soft-deleted items (deleted_at IS NULL)
   * 6. Return cart items with availability status
   *
   * This is a straightforward read operation that provides cart item summary information for customer review before checkout.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get()
  public async index(
    @CustomerAuth()
    customer: CustomerPayload,
  ): Promise<IShoppingMallCart.ISummary> {
    try {
      return await getShoppingMallCustomerCarts({
        customer,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Add a product variant to the customer's shopping cart.
   *
   * This endpoint allows customers to add specific product variants to their shopping cart for potential future purchase. Each cart item represents one product variant selected by the customer with a quantity preference.
   *
   * Key features:
   * - Customers can add multiple variants to their cart for later purchase
   * - Same variant can only exist once per customer (duplicates combine quantities)
   * - Quantity is validated against available stock before adding to cart
   * - Cart items are removed when order is placed
   * - Items become unavailable if variants are deleted or run out of stock
   * - Business logic ensures cart stock validation matches order placement requirements
   *
   * The operation supports the complete shopping workflow from product discovery through cart management to checkout.
   *
   * **Security considerations:**
   * - Only authenticated customers can add items to their cart
   * - Customer can only add items to their own cart (ownership validation)
   * - Stock quantity validation prevents overselling
   * - Variant availability is checked before cart addition
   *
   * **Related operations:**
   * - GET /customers/carts - Retrieve current customer's cart
   * - PATCH /customers/carts/items/{itemId} - Update cart item quantity
   * - DELETE /customers/carts/items/{itemId} - Remove item from cart
   * - POST /orders - Create order from cart (checkouts all items)
   *
   * @param connection
   * @param body Request body for creating a new cart item with variant selection and quantity
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Create new shopping cart item by validating customer ownership, variant availability, and stock quantity.
   * 1. Extract customerId from authenticated session
   * 2. Extract shopping_mall_product_variant_id from request body
   * 3. Validate customer owns the cart (customer_id matches authenticated user)
   * 4. Validate product variant exists and is active
   * 5. Validate requested quantity does not exceed available stock
   * 6. Check if cart item already exists for this customer/variant combination
   * 7. If exists: update quantity (add new quantity to existing)
   * 8. If not exists: create new cart item with current timestamp
   * 9. Set created_at and updated_at timestamps
   * 10. Return created/updated cart item with full details
   * 11. Handle stock validation errors with appropriate error codes
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IShoppingMallCart.ICreate,
  ): Promise<IShoppingMallCart> {
    try {
      return await postShoppingMallCustomerCarts({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update shopping cart items in the customer's cart.
   *
   * This operation allows customers to modify their shopping cart by updating item quantities, validating cart availability, and checking stock levels. It supports batch operations on multiple cart items while ensuring all updates maintain data integrity and stock validation.
   *
   * The operation provides comprehensive cart management capabilities including quantity adjustments, availability validation, and real-time stock checking.
   *
   * @param connection
   * @param body Update request for shopping cart items
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Update shopping cart items with quantity adjustments and validation.
   * Apply batch updates to multiple cart items based on customer request.
   * Validate stock availability for each updated item.
   * Apply business rules for minimum/maximum quantities.
   * Return updated cart totals and availability status.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async patch(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IShoppingMallCart.IUpdate,
  ): Promise<IShoppingMallCart.ISummary> {
    try {
      return await patchShoppingMallCustomerCarts({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update shopping cart item quantity
   *
   * This operation allows customers to modify the quantity of a specific item in their shopping cart. Customers can increase or decrease quantities as needed before proceeding to checkout. The operation supports dynamic quantity adjustments that must respect current stock availability.
   *
   * **Security and Authorization**
   * Only the cart item owner (the customer who added the item) can modify their cart items. The system enforces ownership verification to prevent unauthorized cart modifications by other users.
   *
   * **Business Logic**
   * - Quantity must be a positive integer
   * - Quantity cannot exceed available stock for the variant
   * - If quantity exceeds available stock, the operation will fail with appropriate error message
   * - Cart items with zero or negative quantities are not allowed
   *
   * **Relationship to Other Operations**
   * This operation works in conjunction with:
   * - GET /customers/me/cart - Retrieve current cart state
   * - POST /customers/me/cart - Add new items to cart
   * - DELETE /customers/me/cart/items/{itemId} - Remove items from cart
   *
   * **Expected Behavior**
   * When a customer updates a cart item, the system validates the quantity against current stock, updates the cart item record, and returns the updated cart item with the new total price calculation.
   *
   * @param connection
   * @param cartId Shopping cart item identifier
   * @param body Updated quantity for the cart item
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Update shopping cart item by cart ID with new quantity.
   * Validate that cart item belongs to authenticated customer.
   * Validate quantity is positive integer and does not exceed available stock.
   * Update cart item record with new quantity and updated_at timestamp.
   * Return updated cart item with recalculated subtotal.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":cartId")
  public async putByCartid(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("cartId")
    cartId: string,
    @TypedBody()
    body: IShoppingMallCart.IUpdate,
  ): Promise<IShoppingMallCart> {
    try {
      return await putShoppingMallCustomerCartsCartId({
        customer,
        cartId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Remove a specific shopping cart item for the authenticated customer.
   *
   * This operation deletes a cart item from the customer's shopping cart. The system performs ownership verification to ensure customers can only delete their own cart items.
   *
   * The operation validates that the cart item exists and belongs to the authenticated customer. If the cart item has already been removed or belongs to a different customer, appropriate error responses are returned. The cart item becomes unavailable for purchase immediately upon deletion.
   *
   * This endpoint supports the shopping cart workflow where customers can add items, modify quantities, and remove items before proceeding to checkout.
   *
   * @param connection
   * @param cartId Unique identifier of the shopping cart item to delete. Must be a valid UUID that belongs to the authenticated customer.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Delete shopping cart item with ownership verification.
   * Query shopping_mall_carts table for cart item by ID.
   * Verify cart item's customer_id matches authenticated customer's ID.
   * IF cart item not found, RETURN error CartNotFound.
   * IF cart item belongs to different customer, RETURN error CartAccessDenied.
   * Create soft-delete by setting deleted_at to current timestamp.
   * Remove cart item from customer's active cart display.
   * Return success response with deleted cart item reference.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete(":cartId")
  public async erase(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("cartId")
    cartId: string,
  ): Promise<void> {
    try {
      return await deleteShoppingMallCustomerCartsCartId({
        customer,
        cartId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

